    for byte in bytes {
        if *byte == 0 { view.write_all(b"\x1b[32;57;0;1;8;1_\x1b[32;57;0;0;8;1_")?; } else { view.write_all(&[*byte])?; }
    }
    #[cfg(unix)]
    view.write_all(bytes)?;
    Ok(())
}

